func lengthOfLongestSubstring(s string) int {
	if len(s)<=1{
		return len(s)
	}
	var (
		ans = 1
		hash=map[byte]int{}
		l,r = 0,1
	)
	max:= func(i,j int)int {
		if i>=j{
			return i
		}
		return j
	}
	hash[s[l]] = 0
	//hash[s[r]] = 1
	for r<len(s){
		if v,ok:=hash[s[r]];ok&&v>=l{
			hash[s[r]] = r //左边重复字符出窗，右边重复字符入窗，更新重复字符的最新位置
			ans = max(ans,r-l) // 更新结果
			l = v+1 //更新窗口的左边界
			r++ // 更新窗口右边界
		}else{
			ans=max(ans,r-l+1) //更新结果
			hash[s[r]] = r
			r++ //更新窗口右边界
		}
	}
	return ans


}

