            System.out.printf("%-17s %-6d %-6d %-6d %-6d%n",
                    "\"" + s + "\"",
                    hashSetWhileShrink(s),
                    frequencyMapWhileShrink(s),
                    lastSeenIndexHashMap(s),
                    lastSeenIndexArray(s));
        }
    }
